mapper.select:
SELECT * FROM wf_task
WHERE wf_inst_id = #{instId}
ORDER BY sort ASC, create_time ASC

mapper.update:
UPDATE wf_task
SET task_status = #{newStatus},
    comment = #{comment},
    update_time = NOW()
WHERE wf_task_id = #{taskId}
  AND task_status = #{oldStatus}

UPDATE wf_task
SET task_status = #{newStatus},
    comment = '流程已结束/取消',
    update_time = NOW()
WHERE wf_inst_id = #{instId}
  AND task_status = #{oldStatus}
